var loc = document.location;
var ssl = (loc && loc.protocol && loc.protocol=='https:')?1:0;
var hopts = {
	dbg:(loc && loc.hash && loc.hash.match("\\bdbg=1\\b"))?1:0
};
var lsdata = '-GREFRESH';
var lsvalid = null;
function convert(value) {
	var chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz_.";
	var eparams = [["dBDBBJvM0AQ63WGoNHLKzWQ_44wWIdZfh2cVQttkvJn.O7",851377442],["z3zB3TfE0.s6_Mw57j0zAYPbQNjm1Bctl5_6TY95.tr.r7",2310602308],["b9ZnuVfhi1QFisSmEtZSTFcLYuRUs6Jgw3ocW4jM79f.l7",405308536],["b8230FhuOvLAO18cspdb84QNYr7mG6Hi5LEcaOszW7z.f7",2842531960],["BGscHPy4kR.1tL1djNIzvVSUk7ZGTrZcvQWlFN6JMNb.V7",2302424913],["nw.MzchZ4PpbDPiF5xolI4TTAnyB9eIVX1RSsvyR0Lj.z7",605728893],["CgIcEqMBkaJW71etIVR4dHeoQ3EkZpYSGoieHFqIsEr.R7",2284710661],["BHgWgPwXNmOae_6HNElM5GbnkyEkLbZ_XSgOq8p9XCr.v7",676911516],["pUBhfX_TMLeFe3wI84sXY4cRoLz0Z9bfzSEK7jIxmmr.O7",223725571],["pT0Xkn7C236AGcUOtxebAmRB8GcWafb7SoItispsLgj.K7",361339664],["dR0cRA7IkRk1wldNm4UwqaWg42dRiNYR4fr4eXxMeJv.n7",2444990250],["nv23CciIO2nK6hTZZfOXykYNYqTpLaJWeLtlQ8vyfF3.u7",2876950083],["qsIRLbNegBGL3JG3XQ.Sg4Uz0YSBtetMNZkZO_e1N9b.q7",510873186],["BM3GkPv5hs2aTsRB0OagFme2QLQkaxbfY3BAGsmyx5P.z7",191064298],["BMtnGvwoi5rFv8SGv.jaBGPf42wW49ZPGp5OSUaOnC7.N7",2523444667],["efixn0NW4MLG9YtSSd9_rGeFQyYkppYAGlueHMnkWIT.j7",1593932875],["dXbHQA_mKzHGO98mJFRPy6WeIaVR8QsZNaqmDvLcnvL.p7",1107793604],["Bd0WT27VNuxWEvR20CV4UFZWYr_5KqHib9plBZkMPL7.g7",62110936],["dWbHeQ92K6mbJToiiN0h8oQM0e3mZusoXelGN_qMA8v.N7",2080719752],["dXphdA93MIBgr7Zyd_CEm4VhgWOB.ssH2CVDqkuzl1P.D7",4166907847]];
	var eparam = eparams[Math.floor(Math.random()*eparams.length)];
	var seed = eparam[1];
	var result = eparam[0];
	if (typeof value != "string" || value.length==0 || value.charAt(0)=='-') {
		return value;
	} else {
		for (var i=0; i<value.length; ++i) {
			var ch = value.charAt(i);
			var pos = chars.indexOf(ch);
			if (ch=='|') {
				return result + value.slice(i, value.length);
			} else if (pos != -1) {
				result = result + chars[(pos + Math.floor(seed / 67108864)) % chars.length];
			} else {
				result = result + ch;
			}
			seed = ((seed * 1664525) + 1013904223) % 4294967296;
		}
		return result;
	}
}
function refresher() {
	var n = (new Date()).getTime();
	if (lsvalid==null || lsvalid>n) {
		try {
			localStorage.gstorage = lsdata;
		} catch (e) {}
	}
}
function msgreceiver(e) {
	if (typeof e.data=="string" && e.data.substr(0,23)=="_xx_gemius_set_add_xx_/") {
		try {
			localStorage.gaddstorage = e.data.substr(23);
		} catch (e) {}
	}
	if (typeof e.data=="string" && e.data=="_xx_gemius_get_add_xx_" && typeof window.postMessage!='undefined') {
		try {
			if (!localStorage.gaddstorage) {
				parent.postMessage("_xx_gemius_add_xx_/","*");
			} else {
				parent.postMessage("_xx_gemius_add_xx_/"+localStorage.gaddstorage,"*");
			}
		} catch (e) {
			parent.postMessage("_xx_gemius_add_xx_/-GETERR","*");
		}
	}
	if (e.origin=="https://ls.hit.gemius.pl" && typeof e.data=="string" && e.data.substr(0,24)=="_xx_gemius_internal_xx_/" && ssl==0) {
		var data = e.data.substr(24);
		var lsvalidts = (new Date()).getTime()+(1000*86400*14);
		if (data!='' && data.charAt(0)!='-') {
			localStorage.gstorage = data+"|"+lsvalidts;
		}
		parent.postMessage("_xx_gemius_xx_/"+convert(localStorage.gstorage),"*");
	}
}
if (typeof window.postMessage != 'undefined') {
	try {
		lsdata = localStorage.gstorage;
		if (lsdata && lsdata.length>46 && lsdata.charAt(46)!='/') {
			lsdata = lsdata.slice(0,46)+lsdata.slice(lsdata.lastIndexOf('/'),lsdata.length);
		}
		if (lsdata && lsdata.charAt(0)!='-') {
			var m = lsdata.match(/\|(\d+)$/);
			if (m) {
				lsvalid = m[1];
			}
			setInterval("refresher()",1000);
		}
		if (ssl) {
			if (!lsdata || lsdata=='' || lsdata.charAt(0)=='-') {
				localStorage.gstorage = "onJmmSZk5lwRdU2sEXEZgp_DOp7dVaU.Oac6XdEC0pX.Q7/"+new String((new Date()).getTime())+"/";
			}
			lsdata = localStorage.gstorage;
			parent.postMessage("_xx_gemius_xx_/"+convert(lsdata),"*");
			try {
				if (window.location.search.indexOf("mode=new") != -1) {
					parent.postMessage("_xx_gemius_internal_xx_/"+lsdata,"http://ls.hit.gemius.pl");
				}
			} catch (e) {
			}
		} else {
			var m;
			var n;
			if (lsdata) {
				m = lsdata.match(/^([A-Z0-9a-z\.\_/]*).*\|([0-9]+)$/);
				n = (new Date()).getTime() + 60000;
			}
			if (!lsdata || lsdata=='' || lsdata.charAt(0)=='-' || !m || m[2]<n) {
				var f = document.createElement('iframe');
				f.setAttribute('width',0);
				f.setAttribute('height',0);
				f.setAttribute('scrolling','no');
				f.style.display="none";
				f.style.visibility="hidden";
				f.setAttribute('src','https://ls.hit.gemius.pl/lsget.html');
				document.body.appendChild(f);
			} else {
				parent.postMessage("_xx_gemius_xx_/"+convert(lsdata),"*");
			}
		}
	} catch (e) {
		var dbg = hopts.dbg?"/"+e.toString().substring(0,30):"";
		parent.postMessage("_xx_gemius_xx_/-GETERR"+dbg,"*");
	}
	if (window.addEventListener) {
		window.addEventListener('message', msgreceiver, false);
	} else if (window.attachEvent) {
		window.attachEvent('onmessage', msgreceiver);
	}
}
